const IMAGES = {
  meter: '',
  ocr: ''
};

function fixtureFile(kind) {
  if (!IMAGES[kind]) throw new Error(`Unknown fixture: ${kind}`);
  return {
    name: kind === 'meter' ? 'meter-test.png' : 'ocr-test.png',
    mimeType: 'image/png',
    buffer: Buffer.from(IMAGES[kind], 'base64')
  };
}

module.exports = { fixtureFile };
